// Connecting the factory to a Jira Cloud project with an API token: the
// site, the owner's email and the token are checked against Jira itself,
// which then lists the projects to pick from.
import { Refused } from "../../refused.js";
// A Jira site as its address alone: "https://acme.atlassian.net/" is
// acme.atlassian.net.
export function siteOf(site) {
    return (site
        .trim()
        .replace(/^https?:\/\//, "")
        .split("/")[0] ?? "");
}
// Asking Jira, signed in with the token; a refusal says why in plain words.
function asker(fetcher, login) {
    const site = siteOf(login.site);
    if (!site || !login.email.trim() || !login.token.trim())
        throw new Refused("Give the site, your email and the API token.");
    const auth = Buffer.from(`${login.email.trim()}:${login.token.trim()}`);
    const headers = {
        Authorization: `Basic ${auth.toString("base64")}`,
        Accept: "application/json",
    };
    return async (path) => {
        const answer = await fetcher(`https://${site}${path}`, { headers }).catch(() => {
            throw new Refused(`There is no Jira at ${site}.`);
        });
        if (answer.status === 401 || answer.status === 403)
            throw new Refused("Jira did not accept this email and token.");
        if (!answer.ok)
            throw new Refused(`Jira answered with an error (${String(answer.status)}).`);
        return answer.json();
    };
}
// Who the token belongs to, and the projects it can see.
export async function jiraProjects(fetcher, login) {
    const ask = asker(fetcher, login);
    const me = (await ask("/rest/api/3/myself"));
    const found = (await ask("/rest/api/3/project/search?maxResults=100"));
    return {
        name: me.displayName ?? login.email.trim(),
        projects: (found.values ?? []).map(({ key, name }) => ({ key, name })),
    };
}
// A project's statuses (its board's columns), once each, in order.
export async function jiraColumns(fetcher, login, project) {
    const kinds = (await asker(fetcher, login)(`/rest/api/3/project/${encodeURIComponent(project)}/statuses`));
    return [
        ...new Set(kinds.flatMap((kind) => (kind.statuses ?? []).map((s) => s.name))),
    ];
}
